  "fixed_code": "from django.http import JsonResponse, HttpRequest\nfrom django.views.decorators.http import require_GET\nfrom django.contrib.auth.decorators import login_required\nfrom .models import Article, Order\n\n@login_required\n@require_GET\ndef articles_by_author(request: HttpRequest) -> JsonResponse:\n    \"\"\"Returns a list of articles for a given author with category info.\"\"\"\n    author = request.GET.get(\"author\", \"\")\n    limit = min(int(request.GET.get(\"limit\", 10)), 50)\n    articles = Article.objects.filter(author=author).select_related(\"category\")[:limit]\n    data = [\n        {\"id\": a.id, \"title\": a.title, \"category\": a.category.name if a.category else \"None\"}\n        for a in articles\n    ]\n    return JsonResponse({\"articles\": data})\n\n@login_required\n@require_GET\ndef article_count(request: HttpRequest) -> JsonResponse:\n    \"\"\"Returns the count of articles for a specific author.\"\"\"\n    author = request.GET.get(\"author\", \"\")\n    count = Article.objects.filter(author=author).count()\n    return JsonResponse({\"count\": count})\n\ndef order_summaries():\n    \"\"\"Returns a summary of orders with a hard limit to prevent memory exhaustion.\"\"\"\n    return [\n        {\"id\": o.id, \"customer\": o.customer.name, \"total\": o.total}\n        for o in Order.objects.select_related(\"customer\")[:1000]\n    ]"
